#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string s1 = "Washington";
    std::string s2 = "California";

    // 1. Natural operator syntax
    std::cout << "Operator syntax:\n";
    std::cout << "s1[0] = " << s1[0] << "\n";
    std::cout << "s1 + s2 = " << (s1 + s2) << "\n";
    std::cout << "(s1 < s2) = " << std::boolalpha << (s1 < s2) << "\n";

    // 2. Explicit function call syntax (demonstrating mechanics)
    std::cout << "\nFunction call syntax:\n";
    std::cout << "s1.operator[](0) = " << s1.operator[](0) << "\n";
    std::cout << "operator+(s1, s2) = " << operator+(s1, s2) << "\n";
    std::cout << "operator<(s1, s2) = " << operator<(s1, s2) << "\n";

    std::vector<int> v = {10, 20, 30};
    std::cout << "\nVector access:\n";
    std::cout << "v[1] = " << v[1] << " | v.operator[](1) = " << v.operator[](1) << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <numeric>   // std::gcd in C++17
#include <cmath>     // std::abs

class Rational {
public:
    Rational() : numerator(0), denominator(1) {}

    Rational(int n, int d) {
        int common = std::gcd(std::abs(n), std::abs(d));
        if (common == 0) common = 1;
        numerator = ((d > 0) ? 1 : -1) * n / common;
        denominator = std::abs(d) / common;
    }

    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }

    Rational add(const Rational& second) const {
        int n = numerator * second.denominator + denominator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational subtract(const Rational& second) const {
        int n = numerator * second.denominator - denominator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational multiply(const Rational& second) const {
        int n = numerator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    Rational divide(const Rational& second) const {
        int n = numerator * second.denominator;
        int d = denominator * second.numerator;
        return Rational(n, d);
    }

    int compareTo(const Rational& second) const {
        int lhs = numerator * second.denominator;
        int rhs = denominator * second.numerator;
        if (lhs < rhs) return -1;
        if (lhs > rhs) return 1;
        return 0;
    }

    bool equals(const Rational& second) const {
        return compareTo(second) == 0;
    }

    int intValue() const {
        return numerator / denominator;
    }

    double doubleValue() const {
        return 1.0 * numerator / denominator;
    }

    std::string toString() const {
        if (denominator == 1) return std::to_string(numerator);
        return std::to_string(numerator) + "/" + std::to_string(denominator);
    }

private:
    int numerator;
    int denominator;
};

int main() {
    Rational r1(4, 2); // reduces to 2/1
    Rational r2(2, 3); // 2/3

    std::cout << r1.toString() << " + " << r2.toString() << " = "
              << r1.add(r2).toString() << "\n";
    std::cout << r1.toString() << " - " << r2.toString() << " = "
              << r1.subtract(r2).toString() << "\n";
    std::cout << r1.toString() << " * " << r2.toString() << " = "
              << r1.multiply(r2).toString() << "\n";
    std::cout << r1.toString() << " / " << r2.toString() << " = "
              << r1.divide(r2).toString() << "\n";

    std::cout << "r2.intValue() is " << r2.intValue() << "\n";
    std::cout << "r2.doubleValue() is " << r2.doubleValue() << "\n";
    std::cout << "r1.compareTo(r2) is " << r1.compareTo(r2) << "\n";
    std::cout << "r2.compareTo(r1) is " << r2.compareTo(r1) << "\n";
    std::cout << "r1.compareTo(r1) is " << r1.compareTo(r1) << "\n";
    std::cout << "r1.equals(r1) is " << std::boolalpha << r1.equals(r1) << "\n";
    std::cout << "r1.equals(r2) is " << std::boolalpha << r1.equals(r2) << "\n";

    return 0;
}
